import { useState } from 'react';
import api from '../../api/axiosInstance';
import toast from 'react-hot-toast';
import TokenSlip from '../ui/TokenSlip';
import './TokenFlowModal.css';

const TokenFlowModal = ({ isOpen, onClose }) => {
    const [activeTab, setActiveTab] = useState('generate'); // generate | check
    const [loading, setLoading] = useState(false);
    const [tokenResult, setTokenResult] = useState(null);

    const [genForm, setGenForm] = useState({ name: '', phone: '', address: '', note: '' });
    const [checkCode, setCheckCode] = useState('');

    if (!isOpen) return null;

    const handleGenerate = async (e) => {
        e.preventDefault();
        setLoading(true);
        try {
            const { data } = await api.post('/tokens/generate', genForm);
            setTokenResult(data);
            toast.success('Token generated successfully!');
        } catch (err) {
            toast.error('Failed to generate token');
        } finally {
            setLoading(false);
        }
    };

    const handleCheck = async (e) => {
        e.preventDefault();
        if (!checkCode) return;
        setLoading(true);
        try {
            const { data } = await api.get(`/tokens/check/${checkCode.toUpperCase()}`);
            setTokenResult(data);
        } catch (err) {
            toast.error(err.response?.data?.message || 'Token not found');
            setTokenResult(null);
        } finally {
            setLoading(false);
        }
    };

    const resetAndClose = () => {
        setTokenResult(null);
        setGenForm({ name: '', phone: '', address: '', note: '' });
        setCheckCode('');
        onClose();
    };

    const handlePrint = () => {
        window.print();
    }

    // If we have a result from either Generate or Check, show the TokenSlip
    if (tokenResult) {
        return (
            <div className="token-modal-overlay">
                <div className="text-center w-full px-4">
                    {activeTab === 'generate' ? (
                        <div className="mb-6 animate-fadeUp">
                            <h2 className="text-3xl font-bold font-heading text-white">Success!</h2>
                            <p className="text-[var(--sky3)]">Your service token has been generated.</p>
                        </div>
                    ) : (
                        <div className="mb-6 flex justify-between items-center max-w-sm mx-auto">
                            <button onClick={() => setTokenResult(null)} className="text-[var(--sky)] hover:text-white flex items-center gap-1 font-bold text-sm">
                                ← Back to Search
                            </button>
                            <button onClick={resetAndClose} className="w-8 h-8 rounded-full bg-[var(--card)] border border-[var(--border)] text-white hover:bg-[var(--red)] transition-colors">
                                ×
                            </button>
                        </div>
                    )}
                    <TokenSlip token={tokenResult} onPrint={handlePrint} onClose={resetAndClose} />

                    {/* Additional data for checked tokens that are confirmed */}
                    {activeTab === 'check' && tokenResult.status !== 'waiting' && (
                        <div className="max-w-sm mx-auto mt-6 bg-[var(--card)] p-5 rounded-xl border border-[var(--sky)] animate-fadeUp text-left" style={{ animationDelay: '0.2s' }}>
                            <h3 className="font-bold text-[var(--sky)] mb-3 text-sm tracking-wider uppercase">Service Update</h3>

                            {tokenResult.assignedTechnician && (
                                <div className="flex items-center gap-3 mb-4 bg-[var(--navy)] p-3 rounded-lg border border-[var(--border)]">
                                    <img src={tokenResult.assignedTechnician.avatar} alt="Tech" className="w-10 h-10 rounded-full border border-[var(--sky)]" />
                                    <div>
                                        <p className="font-bold text-white text-sm">{tokenResult.assignedTechnician.name}</p>
                                        <p className="text-xs text-[var(--muted)]">Technician Assigned</p>
                                    </div>
                                    <div className="ml-auto bg-[var(--navy2)] text-[var(--sky)] px-2 py-0.5 rounded text-xs border border-[var(--border)]">
                                        🚗 {tokenResult.assignedTechnician.distanceKm} km
                                    </div>
                                </div>
                            )}

                            {tokenResult.assignedServices?.length > 0 && (
                                <div>
                                    <p className="text-xs text-[var(--muted)] mb-2">Booked Services:</p>
                                    <ul className="space-y-2">
                                        {tokenResult.assignedServices.map(s => (
                                            <li key={s._id} className="text-sm font-bold flex justify-between">
                                                <span className="text-white truncate pr-2">✓ {s.name}</span>
                                                <span className="text-[var(--gold)]">₹{s.price}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return (
        <div className="token-modal-overlay animate-fadeUp">
            <div className="token-modal-content max-w-md w-full animate-pageSlide relative">
                <button onClick={resetAndClose} className="absolute top-4 right-4 text-[var(--muted)] hover:text-white pb-1 w-8 h-8 flex items-center justify-center rounded bg-[var(--navy)] text-xl transition-colors">
                    ×
                </button>

                <div className="flex border-b border-[var(--border)] mb-6">
                    <button
                        className={`flex-1 pb-3 text-center font-bold px-2 border-b-2 transition-colors ${activeTab === 'generate' ? 'border-[var(--gold)] text-[var(--gold)]' : 'border-transparent text-[var(--muted)] hover:text-white'}`}
                        onClick={() => setActiveTab('generate')}
                    >
                        🎫 Get Token
                    </button>
                    <button
                        className={`flex-1 pb-3 text-center font-bold px-2 border-b-2 transition-colors ${activeTab === 'check' ? 'border-[var(--sky)] text-[var(--sky)]' : 'border-transparent text-[var(--muted)] hover:text-white'}`}
                        onClick={() => setActiveTab('check')}
                    >
                        🔍 Check Status
                    </button>
                </div>

                {activeTab === 'generate' ? (
                    <div>
                        <h2 className="text-2xl font-bold font-heading text-white mb-2 text-center">Walk-In Request</h2>
                        <p className="text-xs text-center text-[var(--muted)] mb-6">Generate a token and our support team will contact you directly to arrange the service.</p>

                        <form onSubmit={handleGenerate} className="space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-[var(--gold)] mb-1 uppercase tracking-wider">Full Name *</label>
                                <input required type="text" value={genForm.name} onChange={e => setGenForm({ ...genForm, name: e.target.value })} className="token-input" placeholder="Your Name" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-[var(--gold)] mb-1 uppercase tracking-wider">Mobile Number *</label>
                                <input required type="tel" value={genForm.phone} onChange={e => setGenForm({ ...genForm, phone: e.target.value })} className="token-input font-mono" placeholder="9876543210" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-[var(--gold)] mb-1 uppercase tracking-wider">Address / Area *</label>
                                <input required type="text" value={genForm.address} onChange={e => setGenForm({ ...genForm, address: e.target.value })} className="token-input" placeholder="Kakinada, AP" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-[var(--gold)] mb-1 uppercase tracking-wider">Brief Problem Note</label>
                                <textarea rows="2" value={genForm.note} onChange={e => setGenForm({ ...genForm, note: e.target.value })} className="token-input resize-none" placeholder="E.g., AC not cooling, wire burnt..." />
                            </div>

                            <button type="submit" disabled={loading} className="btn-gold w-full mt-6 py-3 text-lg font-bold">
                                {loading ? 'Generating...' : 'Generate Walk-in Token'}
                            </button>
                        </form>
                    </div>
                ) : (
                    <div>
                        <h2 className="text-2xl font-bold font-heading text-white mb-2 text-center">Track Your Service</h2>
                        <p className="text-xs text-center text-[var(--muted)] mb-6">Enter your 7-character Token Code to check assignment and booking status.</p>

                        <form onSubmit={handleCheck} className="space-y-6">
                            <div className="relative">
                                <input
                                    required
                                    type="text"
                                    value={checkCode}
                                    onChange={e => setCheckCode(e.target.value)}
                                    className="token-input text-center text-3xl tracking-[0.2em] font-mono py-4 uppercase"
                                    placeholder="TKN-XXXX"
                                    maxLength={8}
                                />
                                <div className="absolute inset-0 border border-[var(--sky)] rounded-lg pointer-events-none animate-pulse-sky" style={{ opacity: checkCode.length > 3 ? 1 : 0 }} />
                            </div>

                            <button type="submit" disabled={loading || checkCode.length < 5} className="btn-primary w-full py-3 text-lg font-bold">
                                {loading ? 'Searching...' : 'Lookup Token'}
                            </button>
                        </form>
                    </div>
                )}
            </div>
        </div>
    );
};

export default TokenFlowModal;

import './WorkflowTracker.css';

const WorkflowTracker = ({ step }) => {
    const steps = [
        { num: 1, label: 'Request' },
        { num: 2, label: 'Verify' },
        { num: 3, label: 'Assigned' },
        { num: 4, label: 'Execution' },
        { num: 5, label: 'Complete' }
    ];

    return (
        <div className="workflow-tracker w-full my-6 select-none relative z-10">
            <div className="flex justify-between items-center relative z-20">

                {/* Step Lines Background */}
                <div className="absolute top-4 left-[10%] right-[10%] h-1 bg-[var(--navy)] -z-10 rounded-full" />

                {/* Active Line Fill */}
                <div
                    className="absolute top-4 left-[10%] h-1 rounded-full bg-gradient-to-r from-[var(--sky)] to-[var(--sky2)] transition-all duration-500 -z-10"
                    style={{ width: `${Math.min(100, (step - 1) * 20)}%` }}
                />

                {steps.map((s, i) => {
                    const isActive = step >= s.num;
                    const isCurrent = step === s.num;

                    return (
                        <div key={s.num} className="flex flex-col items-center flex-1 z-20">
                            <div
                                className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm mb-2 border-2 transition-all duration-300 ${isActive
                                        ? 'bg-[var(--sky)] border-[var(--sky)] text-[var(--navy)] shadow-[0_0_15px_rgba(56,189,248,0.5)]'
                                        : 'bg-[var(--card)] border-[var(--border)] text-[var(--muted)]'
                                    } ${isCurrent ? 'animate-pulse-sky scale-110' : ''}`}
                            >
                                {isActive ? '✓' : s.num}
                            </div>
                            <span className={`text-xs font-bold uppercase tracking-wider ${isActive ? 'text-[var(--sky3)]' : 'text-[var(--muted)]'}`}>
                                {s.label}
                            </span>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default WorkflowTracker;

