import { createContext, useContext, useState, useEffect } from 'react';
import api from '../api/axiosInstance';

const AuthContext = createContext();

export function AuthProvider({ children }) {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const token = localStorage.getItem('atnis_token');
        if (token) {
            api.get('/auth/me')
                .then(res => setUser(res.data))
                .catch(() => localStorage.removeItem('atnis_token'))
                .finally(() => setLoading(false));
        } else setLoading(false);
    }, []);

    const login = async (email, password) => {
        const { data } = await api.post('/auth/login', { email, password });
        localStorage.setItem('atnis_token', data.token);
        setUser(data.user);
        return data.user;
    };

    const register = async (form) => {
        const { data } = await api.post('/auth/register', form);
        localStorage.setItem('atnis_token', data.token);
        setUser(data.user);
        return data.user;
    };

    const logout = () => {
        localStorage.removeItem('atnis_token');
        setUser(null);
    };

    return (
        <AuthContext.Provider value={{ user, login, register, logout, loading }}>
            {children}
        </AuthContext.Provider>
    );
}

export const useAuth = () => useContext(AuthContext);

import { useState, useEffect } from 'react';
import api from '../../api/axiosInstance';
import WorkflowTracker from '../components/ui/WorkflowTracker';
import BookingCard from '../components/ui/BookingCard';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

const BookingsPage = () => {
    const { user } = useAuth();
    const [bookings, setBookings] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchBookings = async () => {
        try {
            const { data } = await api.get('/bookings/my');
            setBookings(data);
        } catch (err) {
            toast.error('Failed to load bookings');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchBookings();
    }, []);

    const handleAdvance = async (id) => {
        try {
            await api.put(`/bookings/${id}/advance`);
            toast.success('Booking workflow advanced!');
            fetchBookings();
        } catch (err) {
            toast.error('Could not advance booking step');
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Are you sure you want to cancel this booking?')) return;
        try {
            await api.delete(`/bookings/${id}`);
            toast.success('Booking cancelled successfully');
            setBookings(bookings.filter(b => b._id !== id));
        } catch (err) {
            toast.error('Could not cancel booking');
        }
    };

    if (loading) return <div className="p-12 text-center text-[var(--sky)] font-bold">Loading your active bookings...</div>;

    return (
        <div className="container animate-pageSlide py-12">
            <div className="flex justify-between items-center mb-8 border-b border-[var(--border)] pb-4">
                <div>
                    <h1 className="text-3xl font-bold font-heading text-white">My Bookings</h1>
                    <p className="text-[var(--sky3)] mt-2 font-bold">Manage your active service requests seamlessly.</p>
                </div>
                <div className="bg-[var(--card)] px-4 py-2 rounded-lg border border-[var(--border)] font-mono text-[var(--gold)] text-sm shadow">
                    Active: {bookings.filter(b => b.step < 5).length}
                </div>
            </div>

            {bookings.length === 0 ? (
                <div className="text-center bg-[var(--card)] rounded-xl border border-[var(--border)] py-16 px-6">
                    <div className="text-6xl mb-4">📋</div>
                    <h2 className="text-xl font-bold font-heading text-white mb-2">No active bookings yet</h2>
                    <p className="text-[var(--muted)] mb-6 max-w-sm mx-auto">You haven't requested any services so far. Browse our categories and book a certified technician today.</p>
                    <a href="/" className="btn-primary inline-block">Browse Services</a>
                </div>
            ) : (
                <div className="space-y-12">
                    {bookings.map(booking => (
                        <div key={booking._id} className="bg-[var(--card2)] p-6 rounded-2xl border border-[var(--sky)] shadow-[0_10px_30px_rgba(12,30,53,0.8)] relative isolate overflow-hidden">
                            <div className="absolute inset-0 bg-gradient-to-br from-[var(--navy)] via-transparent to-transparent opacity-50 -z-10" />

                            <BookingCard
                                booking={booking}
                                onAdvance={handleAdvance}
                                onDelete={handleDelete}
                                isAdmin={user?.role === 'Admin'}
                            />

                            <div className="mt-8 bg-[var(--card)] p-6 rounded-xl border border-[var(--border)]">
                                <h3 className="text-sm font-bold font-heading text-white mb-6 uppercase tracking-wider pl-4 border-l-4 border-[var(--sky)]">
                                    Live Service Progress Tracker
                                </h3>
                                <WorkflowTracker step={booking.step} />

                                {booking.step === 5 && (
                                    <div className="text-center mt-8 p-4 bg-[var(--green)]/10 border border-[var(--green)] text-[var(--green)] rounded-lg font-bold flex items-center justify-center gap-2">
                                        <span>🎉</span> Service successfully completed on {new Date(booking.completedAt).toLocaleDateString()}
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default BookingsPage;

import { useState, useEffect, useRef } from 'react';
import { useReactToPrint } from 'react-to-print';
import api from '../../api/axiosInstance';
import toast from 'react-hot-toast';

const InvoicePage = () => {
    const [invoices, setInvoices] = useState([]);
    const [loading, setLoading] = useState(true);

    // Selected invoice for viewing/printing
    const [selectedInvoice, setSelectedInvoice] = useState(null);

    const componentRef = useRef();
    const handlePrint = useReactToPrint({
        content: () => componentRef.current,
        documentTitle: `ATNIS_Invoice_${selectedInvoice?.invoiceNumber}`,
    });

    const fetchInvoices = async () => {
        try {
            const { data } = await api.get('/invoices/my');
            setInvoices(data);
            if (data.length > 0) setSelectedInvoice(data[0]);
        } catch (err) {
            toast.error('Failed to load invoices');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchInvoices();
    }, []);

    const handleDownloadPDF = async (invoiceId, invoiceNum) => {
        try {
            toast.loading('Generating PDF...', { id: 'pdf' });
            const response = await api.get(`/invoices/${invoiceId}/pdf`, {
                responseType: 'blob'
            });

            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', `Invoice-${invoiceNum}.pdf`);
            document.body.appendChild(link);
            link.click();
            link.remove();
            toast.success('Downloaded!', { id: 'pdf' });
        } catch (err) {
            toast.error('Failed to download PDF', { id: 'pdf' });
        }
    };

    if (loading) return <div className="p-12 text-center text-[var(--sky)] font-bold">Loading Invoices...</div>;

    return (
        <div className="container animate-pageSlide py-12 flex flex-col lg:flex-row gap-8">

            {/* Sidebar: Invoice List */}
            <div className="lg:w-1/3 w-full shrink-0">
