                    <div className="bg-[var(--card)] p-6 rounded-xl border border-[var(--border)] text-center">
                        <p className="text-[var(--muted)]">No invoices generated yet.</p>
                    </div>
                ) : (
                    <div className="space-y-3 max-h-[70vh] overflow-y-auto custom-scrollbar pr-2">
                        {invoices.map(inv => (
                            <div
                                key={inv._id}
                                onClick={() => setSelectedInvoice(inv)}
                                className={`p-4 rounded-xl border cursor-pointer transition-all ${selectedInvoice?._id === inv._id ? 'bg-[var(--navy2)] border-[var(--sky)] shadow-[0_0_15px_rgba(56,189,248,0.2)]' : 'bg-[var(--card)] border-[var(--border)] hover:border-[var(--sky3)]'}`}
                            >
                                <div className="flex justify-between items-center mb-2">
                                    <span className="font-mono text-[var(--sky)] text-sm font-bold">{inv.invoiceNumber}</span>
                                    <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded ${inv.status === 'paid' ? 'bg-[var(--green)] text-[var(--navy)]' : 'bg-[var(--gold)] text-[var(--navy)]'}`}>
                                        {inv.status}
                                    </span>
                                </div>
                                <div className="flex justify-between items-center text-white font-bold">
                                    <span>₹{inv.amount}</span>
                                    <span className="text-xs text-[var(--muted)] font-normal">{new Date(inv.date).toLocaleDateString()}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Main Content: Invoice Preview */}
            <div className="lg:w-2/3 w-full">
                {selectedInvoice ? (
                    <>
                        <div className="flex justify-end gap-3 mb-4">
                            <button onClick={handlePrint} className="btn-outline px-4 py-2 text-sm flex items-center gap-2 bg-[var(--card)]">
                                🖨 Print
                            </button>
                            <button onClick={() => handleDownloadPDF(selectedInvoice._id, selectedInvoice.invoiceNumber)} className="btn-primary px-4 py-2 text-sm flex items-center gap-2">
                                📄 Download PDF
                            </button>
                        </div>

                        {/* Printable Area - styled to look good on paper too */}
                        <div className="bg-white text-black p-8 md:p-12 rounded-xl shadow-2xl mx-auto overflow-x-auto" ref={componentRef} style={{ maxWidth: '800px' }}>

                            {/* Header */}
                            <div className="flex justify-between items-start border-b-2 border-slate-200 pb-8 mb-8">
                                <div>
                                    <h2 className="text-4xl font-extrabold text-slate-800 tracking-tighter mb-1">ATNIS.<span className="text-blue-600">⚡</span></h2>
                                    <p className="text-slate-500 text-sm">Unified Service Solution</p>
                                    <p className="text-slate-500 text-sm mt-2">123 Tech Park, Auto Nagar<br />Kakinada, AP 533001</p>
                                    <p className="text-slate-500 text-sm mt-1">support@atnis.in · +91 9876543210</p>
                                </div>
                                <div className="text-right">
                                    <h1 className="text-4xl font-light text-slate-300 uppercase tracking-widest mb-4">Invoice</h1>
                                    <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-sm text-slate-600">
                                        <span className="font-semibold">Invoice No:</span>
                                        <span className="font-mono">{selectedInvoice.invoiceNumber}</span>

                                        <span className="font-semibold">Date:</span>
                                        <span>{new Date(selectedInvoice.date).toLocaleDateString()}</span>

                                        <span className="font-semibold">Status:</span>
                                        <span className={`uppercase font-bold ${selectedInvoice.status === 'paid' ? 'text-green-600' : 'text-amber-500'}`}>{selectedInvoice.status}</span>
                                    </div>
                                </div>
                            </div>

                            {/* Bill To */}
                            <div className="mb-10">
                                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Billed To</h3>
