                                <p className="text-slate-600">Email: {selectedInvoice.userId?.email || 'N/A'}</p>
                                <p className="text-slate-600">Phone: {selectedInvoice.userId?.phone || 'N/A'}</p>
                            </div>

                            {/* Line Items Table */}
                            <table className="w-full mb-8">
                                <thead>
                                    <tr className="border-b border-slate-200 text-left">
                                        <th className="py-3 font-bold text-slate-800 uppercase tracking-wider text-xs">Description</th>
                                        <th className="py-3 font-bold text-slate-800 uppercase tracking-wider text-xs text-right text-right">Amount</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {selectedInvoice.items.map((item, idx) => (
                                        <tr key={idx} className="border-b border-slate-100">
                                            <td className="py-4 text-slate-700">
                                                <p className="font-semibold">{item.serviceName}</p>
                                            </td>
                                            <td className="py-4 text-slate-700 text-right font-mono">₹{item.price.toFixed(2)}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>

                            {/* Totals */}
                            <div className="flex justify-end">
                                <div className="w-1/2 md:w-1/3">
                                    <div className="flex justify-between py-2 border-b border-slate-200">
                                        <span className="text-slate-600 font-semibold">Subtotal</span>
