import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../../api/axiosInstance';
import ServiceDetailCard from '../components/ui/ServiceDetailCard';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

const ServiceDetailPage = () => {
    const { catId } = useParams();
    const navigate = useNavigate();
    const { user } = useAuth();

    const [category, setCategory] = useState(null);
    const [services, setServices] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchCategoryAndServices = async () => {
            try {
                const { data } = await api.get(`/categories/${catId}`);
                setCategory(data.category);
                setServices(data.services);
            } catch (err) {
                toast.error('Failed to load services for this category');
                navigate('/');
            } finally {
                setLoading(false);
            }
        };
        fetchCategoryAndServices();
    }, [catId, navigate]);

    const handleBookService = async (service) => {
        if (!user) {
            toast.error('Please login to book a service');
            // Here usually we'd open the AuthModal via context, but relying on protected routes for now
            return;
        }

        try {
            await api.post('/bookings', {
                serviceId: service._id,
                categoryId: category._id,
                // Optional: Let user pick a technician or leave blank for admin to assign
                // technicianId: selectedTechId, 
                source: 'self'
            });
            toast.success('Booking confirmed! Track it in your Bookings tab.');
            navigate('/bookings');
        } catch (err) {
            toast.error('Failed to create booking. Try again.');
        }
    };

    if (loading) return <div className="p-12 text-center text-[var(--sky)] font-bold">Loading Services...</div>;
    if (!category) return <div className="p-12 text-center text-[var(--red)]">Category not found</div>;

    return (
        <div className="animate-pageSlide min-h-screen pb-12">
            {/* Banner */}
            <div
                className="relative h-[340px] flex items-end justify-center mb-12"
                style={{
                    backgroundImage: `url(${category.image || 'https://images.unsplash.com/photo-1542626991-cbc4e32524cc?q=80&w=2069'})`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center'
                }}
            >
                <div className="absolute inset-0 bg-gradient-to-t from-[var(--navy)] via-[rgba(6,16,31,0.8)] to-transparent" />

                <button onClick={() => navigate('/')} className="absolute top-6 left-6 text-white font-bold bg-[rgba(12,30,53,0.5)] backdrop-blur px-4 py-2 rounded-lg border border-[var(--border)] hover:bg-[var(--sky)] hover:text-[var(--navy)] transition">
                    ← Back to Home
                </button>

                <div className="relative z-10 w-full container text-center pb-8">
                    <div
                        className="w-20 h-20 mx-auto rounded-full flex items-center justify-center text-4xl mb-4 border-[3px] shadow-[0_0_30px_rgba(0,0,0,0.5)] bg-[var(--card)]"
                        style={{ borderColor: category.color, color: category.color }}
                    >
                        {category.icon}
                    </div>
                    <h1 className="text-4xl md:text-5xl font-bold font-heading text-white mb-2" style={{ textShadow: '0 2px 10px rgba(0,0,0,0.5)' }}>
                        {category.name}
                    </h1>
                    <p className="text-[var(--sky3)] max-w-lg mx-auto mb-6 text-lg">{category.tagline}</p>

                    <div className="flex flex-wrap justify-center gap-2 mb-6">
                        <span className="bg-[var(--navy2)] border border-[var(--sky)] text-[var(--sky)] px-3 py-1 rounded-full text-sm font-bold shadow-lg backdrop-blur">
                            {services.length} Services
                        </span>
                        <span className="bg-[var(--navy2)] border border-[var(--gold)] text-[var(--gold)] px-3 py-1 rounded-full text-sm font-bold shadow-lg backdrop-blur">
                            ★ Certified Pros
                        </span>
                        <span className="bg-[var(--navy2)] border border-[var(--green)] text-[var(--green)] px-3 py-1 rounded-full text-sm font-bold shadow-lg backdrop-blur">
                            📍 Local Support
                        </span>
                    </div>

                    <button className="btn-primary" onClick={() => navigate('/technicians', { state: { catId: category._id } })}>
                        👷 View Technicians
                    </button>
                </div>
            </div>

            {/* How it works */}
            <div className="container mb-16 px-4">
                <h2 className="text-2xl font-bold font-heading text-center mb-8">How It Works</h2>
                <div className="flex flex-col md:flex-row justify-between items-center bg-[var(--card)] border border-[var(--border)] p-6 rounded-2xl gap-4 relative isolate">
                    {/* Connecting line for desktop */}
                    <div className="hidden md:block absolute top-[40%] left-[10%] right-[10%] h-[2px] bg-[var(--navy2)] -z-10" />

                    <div className="flex flex-col items-center bg-[var(--card)] px-4">
                        <div className="w-12 h-12 rounded-full bg-[var(--navy2)] border border-[var(--sky)] text-[var(--sky)] flex items-center justify-center text-xl font-bold mb-3 z-10">1</div>
                        <p className="font-bold text-sm">Choose Service</p>
                    </div>
                    <div className="hidden md:block text-[var(--sky)] bg-[var(--card)] px-2">→</div>
                    <div className="flex flex-col items-center bg-[var(--card)] px-4">
                        <div className="w-12 h-12 rounded-full bg-[var(--navy2)] border border-[var(--sky)] text-[var(--sky)] flex items-center justify-center text-xl font-bold mb-3 z-10">2</div>
                        <p className="font-bold text-sm">Verify Request</p>
                    </div>
                    <div className="hidden md:block text-[var(--sky)] bg-[var(--card)] px-2">→</div>
                    <div className="flex flex-col items-center bg-[var(--card)] px-4">
                        <div className="w-12 h-12 rounded-full bg-[var(--navy2)] border border-[var(--gold)] text-[var(--gold)] flex items-center justify-center text-xl font-bold mb-3 animate-pulse-gold z-10">3</div>
                        <p className="font-bold text-sm">Pro Arrives</p>
                    </div>
                    <div className="hidden md:block text-[var(--sky)] bg-[var(--card)] px-2">→</div>
                    <div className="flex flex-col items-center bg-[var(--card)] px-4">
                        <div className="w-12 h-12 rounded-full bg-[var(--navy2)] border border-[var(--green)] text-[var(--green)] flex items-center justify-center text-xl font-bold mb-3 z-10">4</div>
                        <p className="font-bold text-sm">Job Done</p>
                    </div>
                </div>
            </div>

            {/* Services Grid */}
            <div className="container">
                <div className="flex justify-between items-end mb-8 border-b border-[var(--border)] pb-4">
                    <h2 className="text-3xl font-bold font-heading">Available Services</h2>
                </div>

                {services.length === 0 ? (
                    <div className="text-center py-12 bg-[var(--card)] rounded-xl border border-[var(--border)] text-[var(--muted)]">
                        No services currently listed for this category.
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {services.map(service => (
                            <ServiceDetailCard key={service._id} service={service} onBook={handleBookService} />
                        ))}
                    </div>
                )}
            </div>

        </div>
    );
};

