                </div>

                <div className="relative z-10 flex gap-2 mt-6 md:mt-0 bg-[var(--navy2)] p-1 rounded-lg border border-[var(--border)]">
                    <button
                        className={`px-4 py-2 rounded-md text-sm font-bold transition-colors ${filter === 'all' ? 'bg-[var(--sky)] text-[var(--navy)]' : 'text-white hover:bg-[var(--card)]'}`}
                        onClick={() => setFilter('all')}
                    >
                        All Experts
                    </button>
                    <button
                        className={`px-4 py-2 rounded-md text-sm font-bold transition-colors ${filter === 'available' ? 'bg-[var(--green)] text-[var(--navy)]' : 'text-white hover:bg-[var(--card)]'}`}
