import { useState, useEffect } from 'react';
import api from '../../api/axiosInstance';
import toast from 'react-hot-toast';

const TokenQueuePage = () => {
    const [tokens, setTokens] = useState([]);
    const [loading, setLoading] = useState(true);

    // State for assigning resources
    const [technicians, setTechnicians] = useState([]);
    const [services, setServices] = useState([]);
    // Form assignments: tokenId -> { techId, serviceIds }
    const [assignments, setAssignments] = useState({});

    const fetchQueueContext = async () => {
        try {
            setLoading(true);
            const [tokenRes, techRes, servRes] = await Promise.all([
                api.get('/tokens'),
                api.get('/technicians'),
                api.get('/services')
            ]);
            setTokens(tokenRes.data);
            setTechnicians(techRes.data);
            setServices(servRes.data);

            // Initialize assignment state for waiting tokens
            const initialAssignments = {};
            tokenRes.data.forEach(t => {
                if (t.status === 'waiting') {
                    initialAssignments[t._id] = { technicianId: '', serviceIds: [] };
                }
            });
            setAssignments(initialAssignments);
        } catch (err) {
            toast.error('Failed to load queue data');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchQueueContext();
    }, []);

    const handleStatusUpdate = async (id, newStatus) => {
        try {
            await api.put(`/tokens/${id}/status`, { status: newStatus });
            toast.success(`Token marked as ${newStatus}`);
            fetchQueueContext();
        } catch (err) {
            toast.error('Update failed');
        }
    };

    const handleConfirmBooking = async (tokenId) => {
        const assignment = assignments[tokenId];
        if (!assignment.technicianId || assignment.serviceIds.length === 0) {
            return toast.error('Please assign at least 1 technician and 1 service');
        }

        try {
            await api.post(`/tokens/${tokenId}/assign`, {
                technicianId: assignment.technicianId,
                serviceIds: assignment.serviceIds
            });
            toast.success('Token converted to live booking!');
            fetchQueueContext();
        } catch (err) {
            toast.error('Failed to confirm token booking');
        }
    };

    const handleServiceToggle = (tokenId, serviceId) => {
        setAssignments(prev => {
            const current = prev[tokenId];
            const newServiceIds = current.serviceIds.includes(serviceId)
                ? current.serviceIds.filter(id => id !== serviceId)
                : [...current.serviceIds, serviceId];
            return { ...prev, [tokenId]: { ...current, serviceIds: newServiceIds } };
        });
    };

    if (loading) return <div className="p-12 text-center text-[var(--gold)] font-bold">Loading Token Queue...</div>;

    return (
        <div className="container animate-pageSlide py-12">
            <div className="flex justify-between items-center mb-8 border-b border-[var(--border)] pb-4">
                <div>
                    <h1 className="text-3xl font-bold font-heading text-white">Walk-in Token Queue</h1>
                    <p className="text-[var(--gold)] mt-2 font-bold">Admin control center for guest requests.</p>
                </div>
                <div className="bg-[var(--card)] px-4 py-2 rounded-lg border border-[var(--gold)] font-mono text-[var(--gold)] text-sm shadow animate-pulse-gold">
                    Waiting: {tokens.filter(t => t.status === 'waiting').length}
                </div>
            </div>

            <div className="grid grid-cols-1 gap-6">
                {tokens.length === 0 ? (
                    <div className="text-center bg-[var(--card)] rounded-xl border border-[var(--border)] py-12 px-6">
                        <div className="text-4xl mb-4">📭</div>
                        <p className="text-[var(--muted)]">No tokens in the queue right now.</p>
                    </div>
                ) : (
                    tokens.map(token => (
                        <div key={token._id} className={`bg-[var(--card)] rounded-xl border p-6 flex flex-col xl:flex-row gap-6 ${token.status === 'waiting' ? 'border-[var(--gold)] shadow-[0_5px_15px_rgba(245,158,11,0.1)]' : 'border-[var(--border)] opacity-60'}`}>

                            {/* Left: Token Info */}
                            <div className="xl:w-1/3 border-b xl:border-b-0 xl:border-r border-[var(--border)] pb-6 xl:pb-0 xl:pr-6">
                                <div className="flex justify-between items-start mb-4">
                                    <div className="font-mono text-2xl font-bold text-[var(--gold)] bg-[rgba(245,158,11,0.1)] px-3 py-1 rounded border border-[var(--gold)] inline-block">
                                        {token.code}
                                    </div>
                                    <span className={`text-xs px-2 py-1 rounded uppercase font-bold tracking-wider ${token.status === 'waiting' ? 'bg-gray-700 text-white' : token.status === 'confirmed' ? 'bg-[var(--green)] text-[var(--navy)]' : 'bg-[var(--red)] text-white'}`}>
                                        {token.status}
                                    </span>
                                </div>

                                <div className="space-y-2 mb-4">
                                    <p className="text-white font-bold">{token.name}</p>
                                    <p className="text-[var(--sky3)] font-mono text-sm">📞 {token.phone}</p>
                                    <p className="text-[var(--muted)] text-sm">📍 {token.address}</p>
                                </div>

                                {token.note && (
                                    <div className="bg-[var(--navy)] p-3 rounded text-sm text-[var(--muted)] border border-[var(--border)] italic border-l-4 border-l-[var(--sky)]">
                                        "{token.note}"
                                    </div>
                                )}
                            </div>

                            {/* Right: Actions / Assignments */}
                            <div className="xl:w-2/3 flex flex-col justify-between">
                                {token.status === 'waiting' ? (
                                    <>
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                                            {/* Technician Select */}
                                            <div>
                                                <label className="block text-xs font-bold text-[var(--gold)] mb-2 uppercase">1. Assign Technician</label>
                                                <select
                                                    className="w-full bg-[var(--navy)] border border-[var(--border)] text-white rounded p-2 text-sm focus:border-[var(--gold)] outline-none"
                                                    value={assignments[token._id]?.technicianId}
                                                    onChange={e => setAssignments(prev => ({ ...prev, [token._id]: { ...prev[token._id], technicianId: e.target.value } }))}
                                                >
                                                    <option value="">-- Select Available Tech --</option>
                                                    {technicians.filter(t => t.status === 'available').map(tech => (
                                                        <option key={tech._id} value={tech._id}>{tech.name} ({tech.rating}★)</option>
                                                    ))}
                                                </select>
                                            </div>

                                            {/* Service Select (Multi) */}
                                            <div>
                                                <label className="block text-xs font-bold text-[var(--gold)] mb-2 uppercase">2. Assign Services</label>
                                                <div className="bg-[var(--navy)] border border-[var(--border)] rounded p-2 h-32 overflow-y-auto space-y-1 custom-scrollbar">
                                                    {services.map(srv => {
                                                        const isSelected = assignments[token._id]?.serviceIds.includes(srv._id);
                                                        return (
                                                            <div
                                                                key={srv._id}
                                                                onClick={() => handleServiceToggle(token._id, srv._id)}
                                                                className={`p-2 rounded cursor-pointer text-sm flex justify-between items-center transition-colors ${isSelected ? 'bg-[rgba(56,189,248,0.2)] border border-[var(--sky)]' : 'hover:bg-[var(--card2)] border border-transparent'}`}
                                                            >
                                                                <span className={isSelected ? 'text-white font-bold' : 'text-[var(--muted)]'}>{srv.name}</span>
                                                                <span className="text-[var(--gold)] text-xs">₹{srv.price}</span>
                                                            </div>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="flex gap-3 mt-auto">
                                            <button onClick={() => handleConfirmBooking(token._id)} className="flex-1 btn-gold py-2 shadow-lg">
                                                ✅ Confirm & Create Bookings
                                            </button>
                                            <button onClick={() => handleStatusUpdate(token._id, 'expired')} className="btn-outline border-[var(--red)] text-[var(--red)] hover:bg-[rgba(239,68,68,0.1)] px-4">
                                                Mark Expired
                                            </button>
                                        </div>
                                    </>
                                ) : (
                                    <div className="h-full flex items-center justify-center text-[var(--muted)] flex-col gap-2">
                                        <span className="text-4xl">{token.status === 'confirmed' ? '✅' : '❌'}</span>
                                        Token has been processed and is no longer awaiting assignment.
                                    </div>
                                )}
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

export default TokenQueuePage;
